        urlObj.searchParams.forEach((v, k) => addKVRow('paramsList', k, v));
        if ($('paramsList').innerHTML === '') addKVRow('paramsList');
      } catch {
        $('url').value = fullUrl;
      }
    }

    // Extract Headers
    $('headersList').innerHTML = '';
    const headerRegex = /(?:-H|--header)\s+["']([^"']+)["']/g;
    let hMatch;
    let foundHeader = false;
    while ((hMatch = headerRegex.exec(lines)) !== null) {
      const parts = hMatch[1].split(':');
      if (parts.length >= 2) {
        addKVRow('headersList', parts[0].trim(), parts.slice(1).join(':').trim());
        foundHeader = true;
      }
    }
    if (!foundHeader) addKVRow('headersList');

    // Extract Body
    const bodyRegex = /(?:-d|--data|--data-raw|--data-binary)\s+["']({[\s\S]+?})["']|(?:\s+["']({[\s\S]+?})["']$)/;
    const bodyMatch = lines.match(bodyRegex);
    if (bodyMatch) {
      $('body').value = bodyMatch[1] || bodyMatch[2];
      switchSideTab('bodyTab'); // Switch tab if body found? (Actually setupTabs handles display)
    }

    updateMethodColor();
    showToast('cURL Imported');
  } catch (err) {
    console.error(err);
    showToast('Failed to parse cURL');
  }
}

init();

