.tool-name-badge { font-size: 12px; font-family: monospace; background: var(--bg-alt); padding: 4px 8px; border-radius: 4px; border: 1px solid var(--border); color: var(--primary); }

.form-builder { display: flex; flex-direction: column; gap: 16px; margin-bottom: 24px; }
.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-group label { font-size: 12px; font-weight: 600; color: var(--text-secondary); display: flex; justify-content: space-between;}
.form-group label span.type { font-family: monospace; font-size: 10px; color: var(--text-muted); font-weight: normal; }
.form-group input, .form-group textarea {
  background: var(--bg); border: 1px solid var(--border); color: var(--text);
  padding: 10px 12px; border-radius: var(--radius); font-size: 13px; font-family: monospace;
}
.form-group textarea { resize: vertical; min-height: 80px; }
.form-group input:focus, .form-group textarea:focus { border-color: var(--primary); outline: none; box-shadow: 0 0 0 2px var(--accent-subtle, rgba(99, 102, 241, 0.1)); }

.empty-state { padding: 40px; text-align: center; color: var(--text-muted); font-size: 13px; font-style: italic; border: 1px dashed var(--border); border-radius: var(--radius); }
.action-row { display: flex; justify-content: flex-end; margin-top: auto; padding-top: 16px; }

/* OVERVIEW & PREVIEW AREAS */
.section-title { font-size: 11px; font-weight: 700; color: var(--text-muted); margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; flex-shrink: 0; }
pre {
  margin: 0; padding: 16px; background: var(--bg); border-radius: var(--radius);
  font-family: 'JetBrains Mono', 'Fira Code', monospace; font-size: 12px; overflow: auto;
  border: 1px solid var(--border); color: var(--text); flex: 1;
}

/* RIGHT SIDEBAR: CONSOLE */
.console-split { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.console-list { flex: 1; overflow-y: auto; padding: 12px 16px; font-family: monospace; font-size: 12px; display: flex; flex-direction: column; gap: 4px; }

.event-item { padding: 4px 0; border-bottom: 1px solid var(--border-subtle); color: var(--text-secondary); word-break: break-all; }
.event-item .time { color: var(--text-muted); font-size: 10px; margin-right: 6px; }
.event-item.system::before { content: "⚡"; margin-right: 6px; }
.event-item.action::before { content: "▶"; margin-right: 6px; color: var(--primary); }

.log-item { padding: 2px 0; color: var(--text-muted); word-break: break-all; }
.log-item.req { color: var(--color-post); }
.log-item.res { color: var(--success); }

.preview-panel { height: 50%; border-top: 1px solid var(--border); display: flex; flex-direction: column; padding: 16px; background: var(--bg); }

/* TOGGLE COMPONENT */
.theme-switch { position: relative; display: inline-flex; align-items: center; cursor: pointer; gap: 8px; padding: 4px; }
.switch-label { font-size: 11px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; }
.switch-track { position: relative; width: 36px; height: 20px; background: var(--bg-tertiary); border: 1px solid var(--border); border-radius: 20px; transition: var(--transition); }
.switch-track::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; background: var(--text-muted); border-radius: 50%; transition: var(--transition); }
[data-mode="dark"] .switch-track { background: var(--primary); border-color: var(--primary); }
[data-mode="dark"] .switch-track::after { left: 18px; background: white; }

