/* assets/css/components.css - UI Elements */
.brand { font-size: 1.2rem; font-weight: 800; display: flex; align-items: center; gap: 8px; cursor: pointer; }
.brand span { color: var(--accent); }

.btn {
  padding: 8px 16px; border-radius: var(--radius); font-size: 13px; font-weight: 500;
  cursor: pointer; border: 1px solid var(--border); background: var(--bg-tertiary);
  color: var(--text-primary); transition: var(--transition); display: inline-flex; align-items: center; gap: 8px;
}
.btn:hover { background: var(--border); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: white; }
.btn.primary:hover { background: var(--accent-hover); }
.btn.ghost { background: transparent; border-color: transparent; }
.btn.ghost:hover { background: var(--bg-tertiary); }

.url-bar {
  display: flex; gap: 8px; background: var(--bg-secondary);
  border: 1px solid var(--border); border-radius: var(--radius); padding: 4px; margin-bottom: 20px;
}
.method-select {
  background: transparent; border: none; color: var(--text-primary);
  font-weight: 700; padding: 0 12px; outline: none; cursor: pointer;
}
.url-input { flex: 1; background: transparent; border: none; color: var(--text-primary); font-size: 14px; outline: none; }

.tabs { display: flex; gap: 20px; border-bottom: 1px solid var(--border); margin-bottom: 16px; }
.tab {
  padding: 8px 4px; font-size: 13px; color: var(--text-muted); cursor: pointer;
  border-bottom: 2px solid transparent; transition: var(--transition);
}
.tab.active { color: var(--accent); border-bottom-color: var(--accent); }

.tab-content { display: none; }
.tab-content.active { display: block; }

.kv-row { display: flex; gap: 8px; margin-bottom: 8px; }
.kv-row input {
  flex: 1; background: var(--bg-secondary); border: 1px solid var(--border);
  color: var(--text-primary); padding: 8px 12px; border-radius: var(--radius); font-size: 13px; outline: none;
}

textarea {
  width: 100%; min-height: 120px; background: var(--bg-secondary); border: 1px solid var(--border);
  color: var(--text-primary); padding: 12px; border-radius: var(--radius); font-family: monospace; outline: none; resize: vertical;
}

pre {
  background: var(--bg-secondary); padding: 16px; border-radius: var(--radius);
  border: 1px solid var(--border); overflow: auto; font-family: monospace; font-size: 13px; flex: 1;
}

.status-pill { padding: 4px 12px; border-radius: 20px; font-weight: 700; font-size: 12px; }
.status-success { background: rgba(34, 197, 94, 0.1); color: var(--success); }
.status-error { background: rgba(239, 68, 68, 0.1); color: var(--error); }

