/* css/theme.css */
:root {
  color-scheme: dark;
  --bg: #020617;
  --bg-alt: #020617;
  --panel: #020617;
  --border: #1f2937;
  --accent: #38bdf8;
  --text: #e5e7eb;
  --muted: #9ca3af;
  --danger: #f97373;
  --success: #22c55e;
  --radius: 8px;
}

[data-mode="light"] {
  color-scheme: light;
  --bg: #f8fafc;
  --bg-alt: #f1f5f9;
  --panel: #ffffff;
  --border: #e2e8f0;
  --accent: #0284c7;
  --text: #0f172a;
  --muted: #64748b;
  --danger: #ef4444;
  --success: #16a34a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, sans-serif;
  background: radial-gradient(circle at top, var(--bg-alt) 0, var(--bg) 45%, #000 100%);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

[data-mode="light"] body {
  background: var(--bg);
}

