.tab.active { color: var(--accent); border-bottom: 2px solid var(--accent); }
.tab-bar { display:flex; gap:12px; border-bottom:1px solid var(--border); padding-bottom:6px; margin-bottom:6px; overflow-x: auto; scrollbar-width: none;}
.tab-content { display:none; margin-top:6px; flex-direction: column; flex: 1; min-height: 0; overflow-y: auto;}
.tab-content.active { display:flex; }

/* Key Value Rows */
.kv-row { display:flex; gap:8px; margin-bottom:6px; }
.kv-row input { flex:1; }
.small-btn { padding:4px 8px; font-size:11px; border-radius:6px; background: var(--panel); border:1px solid var(--border); color: var(--text); cursor:pointer; }
.small-btn:hover { border-color: var(--accent); color: var(--accent); }

/* Status */
.status-line { font-size: 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; }
.status-pill { border-radius: 999px; padding: 2px 10px; font-size: 11px; border: 1px solid var(--border); color: var(--muted); }
.status-pill.ok { border-color: rgba(34,197,94,0.6); color: var(--success); }
.status-pill.error { border-color: rgba(248,113,113,0.7); color: var(--danger); }
.status-meta { display: flex; gap: 8px; font-size: 11px; color: var(--muted); }

/* Code Blocks */
pre {
  margin: 0; padding: 10px; border-radius: 6px; background: var(--bg); border: 1px solid var(--border);
  font-family: ui-monospace, SFMono-Regular, monospace; font-size: 12px; line-height: 1.4; overflow: auto; flex: 1; min-height: 100px;
}

.mono { font-family: ui-monospace, SFMono-Regular, monospace; }

/* Lists */
.list-item {
  font-size:12px; padding:6px 10px; border-radius:6px; border:1px solid var(--border);
  margin-bottom:6px; cursor:pointer; display:flex; justify-content:space-between; align-items:center;
  background: var(--bg); transition: 0.15s;
}
.list-item:hover { border-color: var(--accent); }
.list-item span.meta { color:var(--muted); font-size:11px; margin-left:8px; }

