// js/core/state.js
const HISTORY_KEY = "lxrest_history";
const SAVED_KEY = "lxrest_saved";
const ENV_KEY = "lxrest_env";

const State = {
  theme: localStorage.getItem('lxrest_theme') || 'dark',

  safeParseJSON(text) {
    if (!text) return null;
    try { return JSON.parse(text); } 
    catch { return null; }
  },

  getHistory() {
    const raw = localStorage.getItem(HISTORY_KEY);
    return this.safeParseJSON(raw) || [];
  },

  pushHistory(entry) {
    const arr = this.getHistory();
    arr.push(entry);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(arr.slice(-200)));
  },

  clearHistory() {
    localStorage.removeItem(HISTORY_KEY);
  },

  getSaved() {
    const raw = localStorage.getItem(SAVED_KEY);
    return this.safeParseJSON(raw) || [];
  },

  saveRequest(entry) {
    const arr = this.getSaved();
    arr.push(entry);
    localStorage.setItem(SAVED_KEY, JSON.stringify(arr));
  },

  deleteSaved(idx) {
    const arr = this.getSaved();
    arr.splice(idx, 1);
    localStorage.setItem(SAVED_KEY, JSON.stringify(arr));
  },

  getEnv() {
    return localStorage.getItem(ENV_KEY) || "";
  },

  setEnv(val) {
    localStorage.setItem(ENV_KEY, val);
  },

  getEnvObject() {
    const txt = this.getEnv();
    const parsed = this.safeParseJSON(txt);
    return parsed && typeof parsed === "object" ? parsed : {};
  },

  applyEnv(str) {
    const env = this.getEnvObject();
    if (!str || !env) return str;
    return str.replace(/{{\s*([\w.-]+)\s*}}/g, (_, key) =>
      env[key] !== undefined ? String(env[key]) : "{{" + key + "}}"
    );
  },

  toggleTheme() {
    this.theme = this.theme === 'light' ? 'dark' : 'light';
    localStorage.setItem('lxrest_theme', this.theme);
    document.documentElement.setAttribute('data-mode', this.theme);
  }
};

window.State = State;

