.switch-track { position: relative; width: 36px; height: 20px; background: var(--bg-tertiary); border: 1px solid var(--border); border-radius: 20px; transition: var(--transition); }
.switch-track::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; background: var(--text-muted); border-radius: 50%; transition: var(--transition); }
[data-mode="dark"] .switch-track { background: var(--primary); border-color: var(--primary); }
[data-mode="dark"] .switch-track::after { left: 18px; background: white; }

