const $ = (id) => document.getElementById(id);
let currentTheme = localStorage.getItem("lxrest_theme") || "dark";
let currentTool = null;

// --- Mock MCP Schema for Notion ---
const mcpTools = [
  {
    id: "search-notion",
    name: "Search Notion",
    desc: "Search across pages and databases.",
    fields: [
      { name: "query", type: "string", placeholder: "e.g., Project Roadmap" },
    ],
  },
  {
    id: "fetch-entity",
    name: "Fetch Notion Entities",
    desc: "Get details of a specific page or block.",
    fields: [
      { name: "entity_id", type: "string", placeholder: "Block or Page ID" },
    ],
  },
  {
    id: "create-page",
    name: "Create Page in Markdown",
    desc: "Quickly generate a page using raw markdown.",
    fields: [
      {
        name: "parent_id",
        type: "string",
        placeholder: "Parent Database/Page ID",
      },
      {
        name: "markdown_content",
        type: "text",
        placeholder: "# Hello World\nThis is auto-generated.",
      },
    ],
  },
  {
    id: "update-page",
    name: "Update Notion Page",
    desc: "Update page properties via JSON.",
    fields: [
      { name: "page_id", type: "string", placeholder: "Page ID" },
      { name: "properties", type: "text", placeholder: '{"Status": "Done"}' },
    ],
  },
  {
    id: "move-pages",
    name: "Move Notion Pages",
    desc: "Move blocks or pages to a new parent.",
    fields: [
      {
        name: "page_or_database_ids",
        type: "string",
        placeholder: "id1, id2 (comma separated)",
      },
      { name: "new_parent", type: "string", placeholder: "New Parent ID" },
    ],
  },
];

function init() {
  setupTabs();
  applyTheme();
  renderTools();

  // Initial Logging
  logEvent("System initialized. Awaiting MCP schema...", "system");
  setTimeout(() => {
    logEvent("Handshake successful. Connected to Notion MCP Server.", "system");
    logConsole("Connected: https://mcp.notion.com/mcp");
  }, 600);
}

// --- Theme Management ---
function toggleTheme() {
  currentTheme = currentTheme === "light" ? "dark" : "light";
  localStorage.setItem("lxrest_theme", currentTheme);
  applyTheme();
}

function applyTheme() {
  document.documentElement.setAttribute("data-mode", currentTheme);
  document.documentElement.setAttribute("data-theme", "lumen"); // Base palette mapping
  $("themeLabel").innerText = currentTheme === "light" ? "Light" : "Dark";
