     </div>`,
    )
    .join("");
}

function selectTool(id) {
  // Update Active State
  document
    .querySelectorAll("#toolList .nav-item")
    .forEach((el) => el.classList.remove("active"));
  $("tool-" + id).classList.add("active");

  // Set Current Tool
  currentTool = mcpTools.find((t) => t.id === id);
  $("currentToolName").innerText = currentTool.id;

  buildForm();
  updatePayload();
  logEvent(`Selected tool: ${currentTool.id}`, "action");
}

// --- Dynamic Form Builder ---
function buildForm() {
  const builder = $("formBuilder");
  if (!currentTool) return;

  let html = `<div style="font-size:12px; color:var(--text-muted); margin-bottom:12px;">${currentTool.desc}</div>`;

  html += currentTool.fields
    .map(
      (f) => `
    <div class="form-group">
      <label>${f.name} <span class="type">${f.type}</span></label>
      ${
        f.type === "text"
          ? `<textarea id="field-${f.name}" placeholder='${f.placeholder || ""}' oninput="updatePayload()" spellcheck="false"></textarea>`
          : `<input type="${f.type}" id="field-${f.name}" placeholder='${f.placeholder || ""}' oninput="updatePayload()" autocomplete="off">`
      }
    </div>
  `,
    )
    .join("");

  builder.innerHTML = html;
}

// --- Payload Overview ---
function updatePayload() {
  if (!currentTool) return;
  const payload = {};

  currentTool.fields.forEach((f) => {
    const el = $(`field-${f.name}`);
    if (el) payload[f.name] = el.value;
  });

  $("payloadPreview").innerText = JSON.stringify(payload, null, 2);
}

