function callTool() {
  if (!currentTool) {
    alert("Please select an MCP tool from the Explorer first.");
    return;
  }

  const btn = $("callToolBtn");
  btn.innerText = "Executing...";
  btn.disabled = true;

  const payloadString = $("payloadPreview").innerText;

  // Logging
  logEvent(`Executing tool: ${currentTool.id}`, "action");
  logConsole(
    `REQ [${currentTool.id}] → ${payloadString.replace(/\n/g, " ")}`,
