          .split(",")
          .map((v) => v.trim())
          .filter((v) => v);
      } else if (prop.type === "object") {
        try {
          val = JSON.parse(val);
        } catch {
          // If invalid JSON, just pass it as string or skip? Let's keep it as is for raw typing, 
          // but for a strict schema, we might want to warn. For now, try to parse, fallback to empty obj if truly empty string, else keep raw.
          if(val === "") val = {};
        }
      } else if (prop.type === "boolean") {
        val = el.checked; // Assuming checkbox for boolean in future, but currently text
      }
      payload[key] = val;
    }
  });

  $("payloadPreview").innerText = JSON.stringify(payload, null, 2);
}

