/* MCP INSPECTOR UI & IDE OVERRIDES */
:root {
  --bg: var(--bg-primary);
  --bg-alt: var(--bg-secondary);
  --bg-tertiary: var(--bg-tertiary);
  --border: var(--border-default);
  --text: var(--text-primary);
  --text-secondary: var(--text-secondary);
  --text-muted: var(--text-muted);

  --primary: var(--accent);
  --primary-hover: var(--accent-hover);
  --success: var(--success);
  --error: var(--error);
  --warning: var(--warning);
  --color-post: var(--method-post);

  --radius: 6px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  margin: 0;
  line-height: 1.5;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  background: var(--bg);
}

/* LAYOUT STRUCTURE */
.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-alt);
  flex-shrink: 0;
}

.layout-container {
  display: flex;
  flex: 1;
  min-height: 0;
}

/* SIDEBARS */
.left-sidebar {
  width: 280px;
  flex-shrink: 0;
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  background: var(--bg-alt);
  transition: margin-left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.left-sidebar.collapsed {
  margin-left: -280px;
}

.right-sidebar {
  width: 520px;
  flex-shrink: 0;
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  background: var(--bg-alt);
  transition: margin-right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.right-sidebar.collapsed {
  margin-right: -320px;
}

/* MIDDLE WORKSPACE */
.middle-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  min-width: 0;
}

.workspace-split {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.builder-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: 16px 24px;
}

.overview-section {
  height: 35%;
  min-height: 200px;
  border-top: 1px solid var(--border);
  padding: 16px 24px;
  background: var(--bg-alt);
  display: flex;
  flex-direction: column;
}

/* BRAND & NAV */
.brand {
  font-size: 1.1rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  display: flex;
  align-items: center;
}
.brand span {
  color: var(--primary);
}
.nav-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* BUTTONS */
button {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  padding: 6px 12px;
  border-radius: var(--radius);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
button:hover {
  background: var(--border);
  color: var(--text);
}
button.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
  padding: 8px 16px;
  font-weight: 600;
}
button.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}
button.ghost {
  background: transparent;
  border-color: transparent;
}
button.ghost:hover {
  background: var(--bg-tertiary);
}
.icon-btn {
  padding: 4px;
  font-size: 16px;
  width: 28px;
  height: 28px;
}

/* LEFT SIDEBAR: NAVIGATION EXPLORER */
.workspace-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  border-bottom: 1px solid var(--border);
}
.ws-info {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ws-avatar {
  width: 24px;
  height: 24px;
  background: var(--primary);
  color: #fff;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: bold;
}
.ws-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
}

.sidebar-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 0;
}
.nav-group {
  margin-bottom: 24px;
}
.nav-group-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  padding: 0 16px 8px;
  letter-spacing: 0.5px;
}
.nav-item {
  padding: 6px 16px 6px 24px;
  font-size: 13px;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  border-left: 2px solid transparent;
  transition: background 0.1s;
}
.nav-item:hover {
  background: var(--bg);
  color: var(--text);
}
.nav-item.active {
  background: var(--accent-subtle, rgba(99, 102, 241, 0.1));
  color: var(--primary);
  border-left-color: var(--primary);
}

/* MIDDLE: ENDPOINT HEADER */
.endpoint-header {
  padding: 16px 24px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-alt);
  flex-shrink: 0;
}
.endpoint-url-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 6px 12px;
}
.method-badge {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-post);
}
.url-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text);
  font-family: monospace;
  font-size: 14px;
  outline: none;
}
.status-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 12px;
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}
.status-badge.connected {
  background: rgba(34, 197, 94, 0.1);
  color: var(--success);
}

/* TABS */
.tabs {
  display: flex;
  gap: 24px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 20px;
  flex-shrink: 0;
}
.tabs.compact {
  gap: 16px;
  padding: 0 16px;
  margin-bottom: 0;
}
.tab {
  padding: 10px 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: var(--transition);
}
.tabs.compact .tab {
  padding: 12px 4px;
}
.tab.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}
.tab-content {
  display: none;
  flex-direction: column;
  flex: 1;
}
.tab-content.active {
  display: flex;
}

/* PARAMETER BUILDER (FORM) */
.builder-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.builder-header h3 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
}
.tool-name-badge {
  font-size: 12px;
  font-family: monospace;
  background: var(--bg-alt);
  padding: 4px 8px;
  border-radius: 4px;
  border: 1px solid var(--border);
  color: var(--primary);
}

.form-builder {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}
.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.form-group label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  display: flex;
  justify-content: space-between;
}
.form-group label span.type {
  font-family: monospace;
  font-size: 10px;
  color: var(--text-muted);
  font-weight: normal;
}
.form-group input,
.form-group textarea {
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 10px 12px;
  border-radius: var(--radius);
  font-size: 13px;
  font-family: monospace;
}
.form-group textarea {
  resize: vertical;
  min-height: 80px;
}
.form-group input:focus,
.form-group textarea:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 2px var(--accent-subtle, rgba(99, 102, 241, 0.1));
}

.empty-state {
  padding: 40px;
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
  font-style: italic;
  border: 1px dashed var(--border);
  border-radius: var(--radius);
}
.action-row {
  display: flex;
  justify-content: flex-end;
  margin-top: auto;
  padding-top: 16px;
}

/* OVERVIEW & PREVIEW AREAS */
.section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
pre {
  margin: 0;
  padding: 16px;
  background: var(--bg);
  border-radius: var(--radius);
  font-family: "JetBrains Mono", "Fira Code", monospace;
  font-size: 12px;
  overflow: auto;
  border: 1px solid var(--border);
  color: var(--text);
  flex: 1;
}

/* RIGHT SIDEBAR: CONSOLE */
.console-split {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}
.console-list {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  font-family: monospace;
  font-size: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.event-item {
  padding: 4px 0;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  word-break: break-all;
}
.event-item .time {
  color: var(--text-muted);
  font-size: 10px;
  margin-right: 6px;
}
.event-item.system::before {
  content: "⚡";
  margin-right: 6px;
}
.event-item.action::before {
  content: "▶";
  margin-right: 6px;
  color: var(--primary);
}

.log-item {
  padding: 2px 0;
  color: var(--text-muted);
  word-break: break-all;
}
.log-item.req {
  color: var(--color-post);
}
.log-item.res {
  color: var(--success);
}

.preview-panel {
  height: 50%;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 16px;
  background: var(--bg);
}

/* TOGGLE COMPONENT */
.theme-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  gap: 8px;
  padding: 4px;
}
.switch-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}
.switch-track {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 20px;
  transition: var(--transition);
}
.switch-track::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  background: var(--text-muted);
  border-radius: 50%;
  transition: var(--transition);
}
[data-mode="dark"] .switch-track {
  background: var(--primary);
  border-color: var(--primary);
}
[data-mode="dark"] .switch-track::after {
  left: 18px;
  background: white;
}

