// assets/js/core/state.js - State Management
const State = {
  theme: localStorage.getItem('lxrest_theme') || 'dark',
  history: JSON.parse(localStorage.getItem('lxrest_history') || '[]'),
  collections: JSON.parse(localStorage.getItem('lxrest_collections') || '[]'),
  environments: JSON.parse(localStorage.getItem('lxrest_env') || '{"Default":{}}'),
  currentEnv: localStorage.getItem('lxrest_current_env') || 'Default',

  saveHistory(item) {
    this.history.unshift(item);
    this.history = this.history.slice(0, 50);
    localStorage.setItem('lxrest_history', JSON.stringify(this.history));
  },

  saveCollection(item) {
    this.collections.unshift(item);
    localStorage.setItem('lxrest_collections', JSON.stringify(this.collections));
  },

  updateTheme(mode) {
    this.theme = mode;
    localStorage.setItem('lxrest_theme', mode);
  }
};

