// assets/js/core/app.js - Main Controller
const App = {
  init() {
    this.applyTheme();
    this.bindEvents();
    this.initUI();
  },

  applyTheme() {
    document.documentElement.setAttribute('data-mode', State.theme);
  },

  bindEvents() {
    // Theme toggle
    document.getElementById('themeToggle').onclick = () => {
      const newTheme = State.theme === 'dark' ? 'light' : 'dark';
      State.updateTheme(newTheme);
      this.applyTheme();
    };

    // Sidebar toggle
    document.getElementById('sidebarToggle').onclick = () => {
      document.querySelector('.sidebar').classList.toggle('collapsed');
    };
  },

  initUI() {
    // Tab switching logic
    document.querySelectorAll('.tab').forEach(tab => {
      tab.onclick = () => {
        const container = tab.closest('.tabs').parentElement;
        const target = tab.dataset.target;

        tab.closest('.tabs').querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        container.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));

        tab.classList.add('active');
        document.getElementById(target).classList.add('active');
      };
    });
  }
};

window.onload = () => App.init();

