args.content:
/* css/components.css */
header h1 { margin: 0; font-size: 18px; letter-spacing: 0.08em; text-transform: uppercase; }
header h1 span { color: var(--accent); }

.panel-title {
  font-size: 12px; text-transform: uppercase; letter-spacing: 0.16em;
  color: var(--muted); margin-bottom: 10px; display: flex; align-items: center; justify-content: space-between;
}
.panel-title span.badge { border-radius: 999px; border: 1px solid var(--border); padding: 2px 8px; font-size: 10px; color: var(--muted); }

.row { margin-bottom: 10px; }
.flex { display: flex; gap: 8px; }
.flex-grow { flex: 1; }

label { display: block; font-size: 11px; text-transform: uppercase; letter-spacing: 0.12em; color: var(--muted); margin-bottom: 4px; }

select, input, textarea, button {
  font-family: inherit; font-size: 13px; border-radius: 6px; border: 1px solid var(--border);
  background: var(--bg); color: var(--text); padding: 7px 9px; outline: none;
}
select:focus, input:focus, textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 1px rgba(56,189,248,0.4); }
input, select { width: 100%; }

textarea {
  width: 100%; min-height: 110px; resize: vertical;
  font-family: ui-monospace, SFMono-Regular, monospace; font-size: 12px; line-height: 1.4;
}

button {
  cursor: pointer; border-radius: 999px; padding-inline: 16px; border-color: rgba(56,189,248,0.5);
  background: radial-gradient(circle at top left, #0ea5e9, #0369a1); color: #e5f3ff; font-weight: 500;
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; transition: 0.15s;
}
button:hover { filter: brightness(1.05); }
button.secondary { background: transparent; border-color: var(--border); color: var(--text); padding-inline: 10px; font-size: 11px; }

/* Tabs */
.tab { padding: 6px 10px; cursor: pointer; font-size: 11px; text-transform: uppercase; letter-spacing: 0.12em; color: var(--muted); }
.tab.active { color: var(--accent); border-bottom: 2px solid var(--accent); }
.tab-bar { display:flex; gap:12px; border-bottom:1px solid var(--border); padding-bottom:6px; margin-bottom:6px; overflow-x: auto; scrollbar-width: none;}
.tab-content { display:none; margin-top:6px; flex-direction: column; flex: 1; min-height: 0; overflow-y: auto;}
.tab-content.active { display:flex; }

/* Key Value Rows */
.kv-row { display:flex; gap:8px; margin-bottom:6px; }
.kv-row input { flex:1; }
.small-btn { padding:4px 8px; font-size:11px; border-radius:6px; background: var(--panel); border:1px solid var(--border); color: var(--text); cursor:pointer; }
.small-btn:hover { border-color: var(--accent); color: var(--accent); }

/* Status */
.status-line { font-size: 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; }
.status-pill { border-radius: 999px; padding: 2px 10px; font-size: 11px; border: 1px solid var(--border); color: var(--muted); }
.status-pill.ok { border-color: rgba(34,197,94,0.6); color: var(--success); }
.status-pill.error { border-color: rgba(248,113,113,0.7); color: var(--danger); }
.status-meta { display: flex; gap: 8px; font-size: 11px; color: var(--muted); }

/* Code Blocks */
pre {
  margin: 0; padding: 10px; border-radius: 6px; background: var(--bg); border: 1px solid var(--border);
  font-family: ui-monospace, SFMono-Regular, monospace; font-size: 12px; line-height: 1.4; overflow: auto; flex: 1; min-height: 100px;
}

.mono { font-family: ui-monospace, SFMono-Regular, monospace; }

/* Lists */
.list-item {
  font-size:12px; padding:6px 10px; border-radius:6px; border:1px solid var(--border);
  margin-bottom:6px; cursor:pointer; display:flex; justify-content:space-between; align-items:center;
  background: var(--bg); transition: 0.15s;
}
.list-item:hover { border-color: var(--accent); }
.list-item span.meta { color:var(--muted); font-size:11px; margin-left:8px; }

