    this._isSyncing = true;

    const urlInput = document.getElementById("url");
    let rawUrl = urlInput.value.trim();

    try {
      // Extract base URL (everything before ?)
      const baseUrlMatch = rawUrl.match(/^([^?]+)/);
      const baseUrl = baseUrlMatch ? baseUrlMatch[1] : rawUrl;

      const params = this.collectKV("paramsList");
      const searchParams = new URLSearchParams();

      params.forEach(([k, v]) => {
        if (k) searchParams.append(k, v);
      });

      const qs = searchParams.toString();
      urlInput.value = qs ? `${baseUrl}?${qs}` : baseUrl;
    } catch (e) {}

    this._isSyncing = false;
  }

  addParam(key = "", value = "") {
    const div = document.createElement("div");
    div.className = "kv-row";
    div.innerHTML = `
      <input placeholder="key" value="${key}">
      <input placeholder="value" value="${value}">
      <button class="small-btn" type="button">x</button>
    `;

    // Bind remove button to also trigger sync
    div.querySelector("button").onclick = () => {
      div.remove();
      this.syncParamsToUrl();
    };

    document.getElementById("paramsList").appendChild(div);
  }

  addHeader(key = "", value = "") {
    const div = document.createElement("div");
    div.className = "kv-row";
    div.innerHTML = `
      <input placeholder="header" value="${key}">
      <input placeholder="value" value="${value}">
      <button class="small-btn" type="button" onclick="this.parentNode.remove()">x</button>
    `;
    document.getElementById("headersList").appendChild(div);
  }

  collectKV(containerId) {
    const rows = document
      .getElementById(containerId)
      .querySelectorAll(".kv-row");
    const out = [];
    rows.forEach((row) => {
      const inputs = row.querySelectorAll("input");
      const k = inputs[0].value.trim();
      const v = inputs[1].value;
      if (k || v) out.push([k, v]); // Collect even if key is empty but value exists
    });
    return out;
  }

  formatBody() {
    const el = document.getElementById("bodyInput");
    const val = el.value.trim();
    if (!val) return;

    try {
      const parsed = JSON.parse(val);
      el.value = JSON.stringify(parsed, null, 2);

      const jsonStatus = document.getElementById("jsonStatus");
      jsonStatus.textContent = "Valid JSON";
      jsonStatus.style.color = "var(--success)";
    } catch (e) {
      alert("Cannot format: Invalid JSON");
    }
  }

  exportState() {
    // Before export, ensure we filter out completely empty KV rows
    const filterEmpty = (kvArray) =>
      kvArray.filter(([k, v]) => k.trim() !== "");

    return {
      method: document.getElementById("method").value,
      url: document.getElementById("url").value,
      params: filterEmpty(this.collectKV("paramsList")),
      headers: filterEmpty(this.collectKV("headersList")),
      body: document.getElementById("bodyInput").value,
      env: document.getElementById("envInput").value,
      authToken: document.getElementById("authToken").value,
      basicUser: document.getElementById("basicUser").value,
      basicPass: document.getElementById("basicPass").value,
    };
  }

  loadState(data) {
    document.getElementById("method").value = data.method || "GET";

    // We set _isSyncing true so setting URL doesn't overwrite params
    this._isSyncing = true;
    document.getElementById("url").value = data.url || "";

    document.getElementById("paramsList").innerHTML = "";
    if (data.params && data.params.length > 0) {
      data.params.forEach(([k, v]) => this.addParam(k, v));
    } else {
      this.addParam();
    }

    this._isSyncing = false; // Restore

    document.getElementById("headersList").innerHTML = "";
    if (data.headers && data.headers.length > 0) {
      data.headers.forEach(([k, v]) => this.addHeader(k, v));
    } else {
      this.addHeader();
    }

    document.getElementById("bodyInput").value = data.body || "";

    // Trigger json validation update
    document.getElementById("bodyInput").dispatchEvent(new Event("input"));

    if (data.env) document.getElementById("envInput").value = data.env;

    document.getElementById("authToken").value = data.authToken || "";
    document.getElementById("basicUser").value = data.basicUser || "";
    document.getElementById("basicPass").value = data.basicPass || "";
  }
}

