const App = {
  init() {
    document.documentElement.setAttribute("data-mode", State.theme);

    Tabs.init();
    Editor.init();
    History.init();

    this.bindEvents();
  },

  bindEvents() {
    document.getElementById("themeBtn").onclick = () => {
      State.toggleTheme();
    };

    document.getElementById("sendBtn").onclick = () => this.handleSend();

    // Keyboard Shortcuts
    document.addEventListener("keydown", (e) => {
      // Ctrl/Cmd + Enter to Send Request
      if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
        e.preventDefault();
        this.handleSend();
      }
    });
  },

  setStatus(text, type) {
    const pill = document.getElementById("statusPill");
    pill.textContent = text;
    pill.className = "status-pill";
    if (type) pill.classList.add(type);
  },

  showCodeGen() {
    const state = Editor.exportState();
    if(!state.url.trim()) return alert("Please enter a URL first.");

    this._codeGenState = state;
    this._currentCodeTab = 'curl';

    document.getElementById('codeModal').style.display = 'flex';
    this.switchCodeTab('curl');
  },

  switchCodeTab(tab) {
    this._currentCodeTab = tab;

    // Update active tab styling
    ['curl', 'fetch', 'axios'].forEach(t => {
      document.getElementById('tab-' + t).classList.remove('active');
    });
    document.getElementById('tab-' + tab).classList.add('active');

    // Generate Code
    const s = this._codeGenState;
    State.setEnv(s.env);

    const url = Transport.buildUrlWithParams(s.url, s.params);
    const headers = Transport.buildHeaders(s.headers, s.authToken, s.basicUser, s.basicPass);
    let body = s.body;

    if (body && !["GET", "HEAD"].includes(s.method)) {
      const bodyApplied = State.applyEnv(body);
      const parsedBody = State.safeParseJSON(bodyApplied);
      if (parsedBody !== null) {
        body = JSON.stringify(parsedBody);
        if (!headers["Content-Type"]) headers["Content-Type"] = "application/json";
      } else {
        body = bodyApplied;
      }
    } else {
        body = null;
    }

    let code = '';

    if (tab === 'curl') {
      code = `curl -X ${s.method} "${url}" \\\n`;
      Object.keys(headers).forEach(k => {
        code += `  -H "${k}: ${headers[k]}" \\\n`;
      });
      if (body) {
        // Escape single quotes for bash
        const escapedBody = body.replace(/'/g, "'\\''");
        code += `  -d '${escapedBody}'`;
      }
      code = code.replace(/ \\\n$/, ''); // Remove trailing slash
    } 
    else if (tab === 'fetch') {
      const opts = { method: s.method, headers: headers };
      if (body) opts.body = 'BODY_PLACEHOLDER';

      let optStr = JSON.stringify(opts, null, 2);
      if (body) {
        optStr = optStr.replace('"BODY_PLACEHOLDER"', `JSON.stringify(${body})`);
      }

      code = `fetch("${url}", ${optStr})\n  .then(response => response.json())\n  .then(data => console.log(data))\n  .catch(error => console.error('Error:', error));`;
    }
    else if (tab === 'axios') {
      const opts = { method: s.method, url: url, headers: headers };
      if (body) opts.data = 'DATA_PLACEHOLDER';

      let optStr = JSON.stringify(opts, null, 2);
      if (body) {
         optStr = optStr.replace('"DATA_PLACEHOLDER"', `JSON.parse('${body.replace(/'/g, "\\'")}')`);
      }

      code = `import axios from 'axios';\n\naxios(${optStr})\n  .then(response => console.log(response.data))\n  .catch(error => console.error(error));`;
    }

    document.getElementById('codeSnippet').innerText = code;
  },

  async handleSend() {
    const state = Editor.exportState();

    if (!state.url.trim()) {
      this.setStatus("Missing URL", "error");
      document.getElementById("respBody").textContent =
        "// please provide a URL";
      return;
    }

    State.setEnv(state.env);

    this.setStatus("Sending…", null);
    document.getElementById("respHeaders").textContent =
      "// waiting for response…";
    document.getElementById("respBody").textContent = "";
    document.getElementById("timeInfo").textContent = "… ms";
    document.getElementById("sizeInfo").textContent = "… B";
    document.getElementById("metaInfo").textContent = "";

    try {
      const res = await Transport.execute({
        method: state.method,
        rawUrl: state.url,
        params: state.params,
        headersList: state.headers,
        bodyText: state.body,
        authToken: state.authToken,
        basicUser: state.basicUser,
        basicPass: state.basicPass,
      });

      this.setStatus(
        `${res.status} ${res.statusText}`,
        res.ok ? "ok" : "error",
      );
      document.getElementById("timeInfo").textContent = res.duration + " ms";
      document.getElementById("sizeInfo").textContent = res.size + " B";

      let headerText = "";
      res.headers.forEach((v, k) => {
        headerText += `${k}: ${v}\n`;
      });
      document.getElementById("respHeaders").textContent =
        headerText || "// no headers";

      const json = State.safeParseJSON(res.body);
      if (json !== null) {
        document.getElementById("respBody").textContent = JSON.stringify(
          json,
          null,
          2,
        );
        document.getElementById("metaInfo").textContent = "JSON";
      } else {
        document.getElementById("respBody").textContent =
