  transition: 0.15s;
}
button:hover {
  filter: brightness(1.05);
}
button.secondary {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
  padding-inline: 10px;
  font-size: 11px;
}

/* Icon Button */
button.icon-btn {
  padding: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
[data-mode="dark"] #ico-moon {
  display: none;
}
[data-mode="light"] #ico-sun {
  display: none;
}

/* Tabs */
.tab {
  padding: 6px 10px;
  cursor: pointer;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}
.tab.active {
  color: var(--accent);
  border-bottom: 2px solid var(--accent);
}
.tab-bar {
  display: flex;
  gap: 12px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 6px;
  margin-bottom: 6px;
  overflow-x: auto;
  scrollbar-width: none;
}
.tab-content {
  display: none;
  margin-top: 6px;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.tab-content.active {
  display: flex;
}

/* Key Value Rows */
.kv-row {
  display: flex;
  gap: 8px;
  margin-bottom: 6px;
}
.kv-row input {
  flex: 1;
}
.small-btn {
  padding: 4px 8px;
  font-size: 11px;
  border-radius: 6px;
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--text);
  cursor: pointer;
}
.small-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* Status */
.status-line {
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}
.status-pill {
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 11px;
  border: 1px solid var(--border);
  color: var(--muted);
}
.status-pill.ok {
  border-color: rgba(34, 197, 94, 0.6);
  color: var(--success);
}
.status-pill.error {
  border-color: rgba(248, 113, 113, 0.7);
  color: var(--danger);
}
.status-meta {
  display: flex;
  gap: 8px;
  font-size: 11px;
  color: var(--muted);
}

/* Code Blocks */
pre {
  margin: 0;
  padding: 10px;
  border-radius: 6px;
  background: var(--bg);
  border: 1px solid var(--border);
  font-family: ui-monospace, SFMono-Regular, monospace;
  font-size: 12px;
  line-height: 1.4;
  overflow: auto;
  flex: 1;
  min-height: 100px;
}

.mono {
  font-family: ui-monospace, SFMono-Regular, monospace;
}

/* Lists */
.list-item {
  font-size: 12px;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid var(--border);
  margin-bottom: 6px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  transition: 0.15s;
}
.list-item:hover { border-color: var(--accent); }
.list-item span.meta { color:var(--muted); font-size:11px; margin-left:8px; }

/* Status Indicators */
.local-indicator-dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--success);
  box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.25);
}
.local-indicator-text {
  display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--muted);
}

/* Modals */
.modal-overlay {
  display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: rgba(0, 0, 0, 0.6); z-index: 50; align-items: center; justify-content: center; backdrop-filter: blur(4px);
}
.modal-panel {
  width: 600px; max-width: 90vw; max-height: 80vh; overflow: hidden; background: var(--bg);
}

/* Auth Helpers */
.auth-helper { font-size: 10px; color: var(--muted); margin-top: 4px; }
.auth-divider { border-top: 1px solid var(--border); padding-top: 16px; }

