+function importFromCurl() {
+  const curl = prompt('Paste cURL command here:');
+  if (!curl) return;
+
+  try {
+    const lines = curl.split('\n').join(' ');
+    
+    // Simple parser
+    let method = 'GET';
+    if (lines.includes('-X POST') || lines.includes('--request POST')) method = 'POST';
+    else if (lines.includes('-X PUT') || lines.includes('--request PUT')) method = 'PUT';
+    else if (lines.includes('-X PATCH') || lines.includes('--request PATCH')) method = 'PATCH';
+    else if (lines.includes('-X DELETE') || lines.includes('--request DELETE')) method = 'DELETE';
