+
+    // Extract URL (look for http... in quotes or not)
+    const urlMatch = lines.match(/(?:'|")?(https?:\/\/[^\s'"]+)(?:'|")?/);
+    if (urlMatch) {
+      let fullUrl = urlMatch[1];
+      try {
