resultDisplay.originalContent:
/* MINIMALIST OVERRIDES & ADAPTATIONS */
:root {
  --bg: var(--bg-primary);
  --bg-alt: var(--bg-secondary);
  --border: var(--border-default);
  --text: var(--text-primary);
  --text-secondary: var(--text-secondary);
  --text-muted: var(--text-muted);

  --primary: var(--accent);
  --primary-hover: var(--accent-hover);
  --success: var(--success);
  --error: var(--error);
  --warning: var(--warning);

  --color-get: var(--method-get);
  --color-post: var(--method-post);
  --color-put: var(--method-put);
  --color-patch: var(--method-patch);
  --color-delete: var(--method-delete);

  --radius: 8px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  margin: 0;
  line-height: 1.5;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

/* LAYOUT & GRID */
.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  background: var(--bg);
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 24px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
  flex-shrink: 0;
}

.layout-container {
  display: flex;
  flex: 1;
  min-height: 0;
}

.left-sidebar {
  width: 260px;
  flex-shrink: 0;
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  background: var(--bg-alt);
  transition: margin-left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.left-sidebar.collapsed {
  margin-left: -260px;
}

.middle-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  min-width: 0;
}

.right-sidebar {
  width: 260px;
  flex-shrink: 0;
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  background: var(--bg-alt);
  transition: margin-right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.right-sidebar.collapsed {
  margin-right: -260px;
}

.request-section {
  height: 40%;
  border-bottom: 1px solid var(--border);
  padding: 20px 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.response-section {
  height: 60%;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  background: var(--bg-alt);
  overflow: hidden;
}

/* COMPONENTS */
.brand {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand span {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 8px;
}

button {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  padding: 8px 16px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
button:hover {
  background: var(--border);
  color: var(--text);
}
button.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}
button.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}
button.ghost {
  background: transparent;
  border-color: transparent;
}
button.ghost:hover {
  background: var(--bg-alt);
}

.request-bar {
  display: flex;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 4px;
  gap: 4px;
  margin-bottom: 16px;
  transition: var(--transition);
  flex-shrink: 0;
}
.request-bar:focus-within {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}
.method-select {
  background: transparent;
  border: none;
  color: var(--text);
  font-weight: 700;
  font-size: 13px;
  padding: 0 12px;
  cursor: pointer;
  outline: none;
  text-transform: uppercase;
}
.url-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text);
  font-family: inherit;
  font-size: 15px;
  padding: 8px 4px;
  outline: none;
}

.tabs {
  display: flex;
  gap: 24px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
  flex-shrink: 0;
}
.tab {
  padding: 8px 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: var(--transition);
}
.tab.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.request-section .tab-content {
  display: none;
  flex-direction: column;
  flex: 1;
  overflow-y: auto;
}
.request-section .tab-content.active {
  display: flex;
}

.kv-row {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}
.kv-row input {
  flex: 1;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 8px 12px;
  border-radius: var(--radius);
  font-size: 13px;
  outline: none;
}
.kv-row input:focus {
  border-color: var(--primary);
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  flex-shrink: 0;
}

.meta-group {
  display: flex;
  gap: 16px;
  font-size: 12px;
  font-family: monospace;
}
.status-pill {
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
}
.status-ok {
  background: rgba(34, 197, 94, 0.1);
  color: var(--success);
}
.status-err {
  background: rgba(239, 68, 68, 0.1);
  color: var(--error);
}

.response-section .tab-content {
  display: none;
  flex: 1;
  min-height: 0;
  flex-direction: column;
}
.response-section .tab-content.active {
  display: flex;
}

pre {
  margin: 0;
  padding: 16px;
  background: var(--bg);
  border-radius: var(--radius);
  font-family: "JetBrains Mono", "Fira Code", monospace;
  font-size: 13px;
  overflow: auto;
  border: 1px solid var(--border);
  color: var(--text-secondary);
  flex: 1;
}

textarea {
  width: 100%;
  flex: 1;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 16px;
  border-radius: var(--radius);
  font-family: monospace;
  outline: none;
  resize: none;
}

/* SIDEBARS */
.sidebar-header {
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.sidebar-tabs {
  display: flex;
  padding: 0 20px 12px;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.sidebar-tab {
  flex: 1;
  padding: 6px;
  text-align: center;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  border-radius: 4px;
  cursor: pointer;
  color: var(--text-muted);
  transition: var(--transition);
}
.sidebar-tab.active {
  background: var(--bg);
  color: var(--primary);
}
.sidebar-body {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
}

.list-item {
  padding: 10px 12px;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: var(--transition);
}
.list-item:hover {
  background: var(--bg);
}
.list-item .method {
  font-size: 10px;
  font-weight: 800;
  min-width: 45px;
}
.list-item .url {
  font-size: 13px;
  color: var(--text-secondary);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

#toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(100px);
  background: var(--text);
  color: var(--bg);
  padding: 10px 20px;
  border-radius: 50px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1000;
}
#toast.show {
  transform: translateX(-50%) translateY(0);
}

.theme-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  gap: 8px;
  padding: 4px;
}
.switch-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}
.switch-track {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 20px;
  transition: var(--transition);
}
.switch-track::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  background: var(--text-muted);
  border-radius: 50%;
  transition: var(--transition);
}
[data-mode="dark"] .switch-track {
  background: var(--primary);
  border-color: var(--primary);
}
[data-mode="dark"] .switch-track::after {
  left: 18px;
  background: white;
}

.hidden {
  display: none !important;
}

