const $ = id => document.getElementById(id);
let currentTheme = localStorage.getItem('lxrest_theme') || 'dark';
let currentTool = null;

// --- Mock MCP Schema for Notion ---
const mcpTools = [
  { 
    id: "search-notion", 
    name: "Search Notion", 
    desc: "Search across pages and databases.",
    fields: [{ name: "query", type: "string", placeholder: "e.g., Project Roadmap" }] 
  },
  { 
    id: "fetch-entity", 
    name: "Fetch Notion Entities", 
    desc: "Get details of a specific page or block.",
    fields: [{ name: "entity_id", type: "string", placeholder: "Block or Page ID" }] 
  },
  { 
    id: "create-page", 
    name: "Create Page in Markdown", 
    desc: "Quickly generate a page using raw markdown.",
    fields: [
      { name: "parent_id", type: "string", placeholder: "Parent Database/Page ID" }, 
      { name: "markdown_content", type: "text", placeholder: "# Hello World\nThis is auto-generated." }
    ] 
  },
  { 
    id: "update-page", 
    name: "Update Notion Page", 
    desc: "Update page properties via JSON.",
    fields: [
      { name: "page_id", type: "string", placeholder: "Page ID" }, 
      { name: "properties", type: "text", placeholder: '{"Status": "Done"}' }
    ] 
  },
  { 
    id: "move-pages", 
    name: "Move Notion Pages", 
    desc: "Move blocks or pages to a new parent.",
    fields: [
      { name: "page_or_database_ids", type: "string", placeholder: "id1, id2 (comma separated)" }, 
      { name: "new_parent", type: "string", placeholder: "New Parent ID" }
    ] 
  }
];

function init() {
  setupTabs();
  applyTheme();
  renderTools();

  // Initial Logging
  logEvent('System initialized. Awaiting MCP schema...', 'system');
  setTimeout(() => {
    logEvent('Handshake successful. Connected to Notion MCP Server.', 'system');
    logConsole('Connected: https://mcp.notion.com/mcp');
  }, 600);
}

// --- Theme Management ---
function toggleTheme() {
  currentTheme = currentTheme === 'light' ? 'dark' : 'light';
  localStorage.setItem('lxrest_theme', currentTheme);
  applyTheme();
}

function applyTheme() {
  document.documentElement.setAttribute('data-mode', currentTheme);
  document.documentElement.setAttribute('data-theme', 'lumen'); // Base palette mapping
  $('themeLabel').innerText = currentTheme === 'light' ? 'Light' : 'Dark';
}

// --- Layout Toggles ---
function toggleSidebar(side) {
  const sidebar = side === 'left' ? document.querySelector('.left-sidebar') : document.querySelector('.right-sidebar');
  sidebar.classList.toggle('collapsed');
}

// --- Tab Logic ---
function setupTabs() {
  document.querySelectorAll('.tab').forEach(tab => {
    tab.onclick = () => {
      const parent = tab.closest('.tabs');
      const container = parent.nextElementSibling.parentElement; // Scoped to nearest container
      const target = tab.dataset.target;

      parent.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      container.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));

      tab.classList.add('active');
      $(target).classList.add('active');
    };
  });
}

// --- Tool Explorer Logic ---
function renderTools() {
  const list = $('toolList');
  list.innerHTML = mcpTools.map(t => 
    `<div class="nav-item" onclick="selectTool('${t.id}')" id="tool-${t.id}">
       <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="margin-right:4px;"><polyline points="16 18 22 12 16 6"></polyline><polyline points="8 6 2 12 8 18"></polyline></svg>
       ${t.name}
     </div>`
  ).join('');
}

function selectTool(id) {
  // Update Active State
  document.querySelectorAll('#toolList .nav-item').forEach(el => el.classList.remove('active'));
  $('tool-' + id).classList.add('active');

  // Set Current Tool
  currentTool = mcpTools.find(t => t.id === id);
  $('currentToolName').innerText = currentTool.id;

  buildForm();
  updatePayload();
  logEvent(`Selected tool: ${currentTool.id}`, 'action');
}

// --- Dynamic Form Builder ---
function buildForm() {
  const builder = $('formBuilder');
  if (!currentTool) return;

  let html = `<div style="font-size:12px; color:var(--text-muted); margin-bottom:12px;">${currentTool.desc}</div>`;

  html += currentTool.fields.map(f => `
    <div class="form-group">
      <label>${f.name} <span class="type">${f.type}</span></label>
      ${f.type === 'text' 
        ? `<textarea id="field-${f.name}" placeholder='${f.placeholder || ''}' oninput="updatePayload()" spellcheck="false"></textarea>`
        : `<input type="${f.type}" id="field-${f.name}" placeholder='${f.placeholder || ''}' oninput="updatePayload()" autocomplete="off">`
      }
    </div>
  `).join('');

  builder.innerHTML = html;
}

// --- Payload Overview ---
function updatePayload() {
  if (!currentTool) return;
  const payload = {};

  currentTool.fields.forEach(f => {
    const el = $(`field-${f.name}`);
    if (el) payload[f.name] = el.value;
  });

  $('payloadPreview').innerText = JSON.stringify(payload, null, 2);
}

// --- Execute Mock MCP Tool ---
function callTool() {
  if (!currentTool) {
    alert("Please select an MCP tool from the Explorer first.");
    return;
  }

  const btn = $('callToolBtn');
  btn.innerText = 'Executing...';
  btn.disabled = true;

  const payloadString = $('payloadPreview').innerText;

  // Logging
  logEvent(`Executing tool: ${currentTool.id}`, 'action');
  logConsole(`REQ [${currentTool.id}] → ${payloadString.replace(/\n/g, ' ')}`, 'req');

  $('responsePreview').innerText = '// Awaiting server response...';

  // Mock Latency (Network Simulation)
  setTimeout(() => {
    btn.innerText = 'Call Tool';
    btn.disabled = false;

    // Mock Response Data based on tool
    const mockRes = {
      _mcp_meta: { status: 200, latency_ms: 450, trace_id: `tr_${Math.floor(Math.random()*100000)}` },
      tool: currentTool.id,
      success: true,
      data: currentTool.id === 'search-notion' 
        ? [ { id: "page_123", title: "Project Alpha", url: "https://notion.so/123" } ]
        : { message: "Operation completed successfully.", affected_rows: 1 }
    };

    $('responsePreview').innerText = JSON.stringify(mockRes, null, 2);

    logEvent(`Execution complete: ${currentTool.id}`, 'system');
    logConsole(`RES [200 OK] ← ${JSON.stringify(mockRes.data)}`, 'res');

  }, 850);
}

// --- Observability Logs ---
function logEvent(msg, type = 'system') {
  const el = document.createElement('div');
  el.className = `event-item ${type}`;
  const time = new Date().toLocaleTimeString('en-US', { hour12: false });
  el.innerHTML = `<span class="time">[${time}]</span> ${msg}`;
  $('eventsTab').prepend(el);
}

function logConsole(msg, type = 'log') {
  const el = document.createElement('div');
  el.className = `log-item ${type}`;
  el.innerText = `> ${msg}`;
  $('consoleTab').prepend(el);
}

// Initialize application
init();

