const $ = id => document.getElementById(id);
let currentTheme = localStorage.getItem('lxrest_theme') || 'dark';
let currentTool = null;

/**
 * PHASE 1: MCP SCHEMA ENGINE
 * Handles dynamic tool discovery and complex form generation
 */

// --- Real-world Mock MCP Tool Schemas (JSON Schema inspired) ---
const mcpTools = [
  {
    name: "notion-move-pages",
    description: "Move Notion pages or databases to a new parent location.",
    inputSchema: {
      type: "object",
      properties: {
        page_or_database_ids: {
          type: "array",
          items: { type: "string" },
          description: "List of Notion IDs to move."
        },
        new_parent: {
          type: "string",
          description: "ID of the target parent page or database."
        },
        priority: {
          type: "string",
          enum: ["low", "medium", "high"],
          default: "medium"
        }
      },
      required: ["page_or_database_ids", "new_parent"]
    }
  },
  {
    name: "notion-search",
    description: "Search for pages or databases in Notion.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "Search term" },
        filter: {
          type: "object",
          properties: {
            property: { type: "string" },
            value: { type: "string" }
          }
        }
      },
      required: ["query"]
    }
  }
];

function init() {
  setupTabs();
  applyTheme();
  renderTools();
  logEvent('System initialized. Discovery started...', 'system');
}

// --- Theme & Layout Toggles ---
function toggleTheme() {
  currentTheme = currentTheme === 'light' ? 'dark' : 'light';
  localStorage.setItem('lxrest_theme', currentTheme);
  applyTheme();
}

function applyTheme() {
  document.documentElement.setAttribute('data-mode', currentTheme);
  $('themeLabel').innerText = currentTheme === 'light' ? 'Light' : 'Dark';
}

function toggleSidebar(side) {
  const sidebar = side === 'left' ? document.querySelector('.left-sidebar') : document.querySelector('.right-sidebar');
  sidebar.classList.toggle('collapsed');
}

// --- Tab Logic ---
function setupTabs() {
  document.querySelectorAll('.tab').forEach(tab => {
    tab.onclick = () => {
      const parent = tab.closest('.tabs');
      const container = parent.nextElementSibling.parentElement;
      const target = tab.dataset.target;
      parent.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      container.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
      tab.classList.add('active');
      $(target).classList.add('active');
    };
  });
}

// --- Tool Explorer ---
function renderTools() {
  const list = $('toolList');
  list.innerHTML = mcpTools.map(t => `
    <div class="nav-item" onclick="selectTool('${t.name}')" id="tool-${t.name}">
       <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="margin-right:8px;"><polyline points="16 18 22 12 16 6"></polyline><polyline points="8 6 2 12 8 18"></polyline></svg>
       ${t.name}
    </div>
  `).join('');
}

function selectTool(name) {
  document.querySelectorAll('#toolList .nav-item').forEach(el => el.classList.remove('active'));
  $('tool-' + name).classList.add('active');

  currentTool = mcpTools.find(t => t.name === name);
  $('currentToolName').innerText = currentTool.name;

  generateSchemaForm(currentTool.inputSchema);
  updatePayload();
  logEvent(`Tool selected: ${currentTool.name}`, 'action');
}

// --- SCHEMA ENGINE: DYNAMIC FORM GENERATOR ---
function generateSchemaForm(schema) {
  const container = $('formBuilder');
  container.innerHTML = `<div style="font-size:12px; color:var(--text-muted); margin-bottom:16px;">${currentTool.description}</div>`;

  if (!schema.properties) return;

  const html = Object.entries(schema.properties).map(([key, prop]) => {
    const isRequired = schema.required?.includes(key);
    return renderField(key, prop, isRequired);
  }).join('');

  container.innerHTML += html;
}

function renderField(name, prop, required) {
  let inputHtml = '';

  if (prop.enum) {
    inputHtml = `
      <select id="field-${name}" onchange="updatePayload()">
        ${prop.enum.map(v => `<option value="${v}" ${v === prop.default ? 'selected' : ''}>${v}</option>`).join('')}
      </select>
    `;
  } else if (prop.type === 'array') {
    inputHtml = `<input type="text" id="field-${name}" placeholder="Value1, Value2..." oninput="updatePayload()">`;
  } else if (prop.type === 'object') {
    inputHtml = `<textarea id="field-${name}" placeholder='{"key": "value"}' oninput="updatePayload()"></textarea>`;
  } else {
    inputHtml = `<input type="text" id="field-${name}" placeholder="${prop.description || ''}" oninput="updatePayload()">`;
  }

  return `
    <div class="form-group">
      <label>
        ${name} ${required ? '<span style="color:var(--error)">*</span>' : ''}
        <span class="type">${prop.type}</span>
      </label>
      ${inputHtml}
    </div>
  `;
}

function updatePayload() {
  if (!currentTool) return;
  const payload = {};

  Object.entries(currentTool.inputSchema.properties).forEach(([key, prop]) => {
    const el = $(`field-${key}`);
    if (!el) return;

    let val = el.value;
    if (prop.type === 'array') val = val.split(',').map(v => v.trim()).filter(v => v);
    if (prop.type === 'object') {
      try { val = JSON.parse(val); } catch { val = {}; }
    }
    payload[key] = val;
  });

  $('payloadPreview').innerText = JSON.stringify(payload, null, 2);
}

// --- Observability & Call (Phase 1 Stub) ---
function callTool() {
  logEvent(`Executing ${currentTool.name}...`, 'action');
  logConsole(`REQ → ${$('payloadPreview').innerText}`, 'req');

  setTimeout(() => {
    const mockRes = { success: true, timestamp: Date.now() };
    $('responsePreview').innerText = JSON.stringify(mockRes, null, 2);
    logConsole(`RES ← OK`, 'res');
  }, 500);
}

function logEvent(msg, type = 'system') {
  const el = document.createElement('div');
  el.className = `event-item ${type}`;
  el.innerHTML = `<span class="time">[${new Date().toLocaleTimeString()}]</span> ${msg}`;
  $('eventsTab').prepend(el);
}

function logConsole(msg, type = 'log') {
  const el = document.createElement('div');
  el.className = `log-item ${type}`;
  el.innerText = `> ${msg}`;
  $('consoleTab').prepend(el);
}

init();

