// js/core/app.js
const App = {
  init() {
    document.documentElement.setAttribute("data-mode", State.theme);

    Tabs.init();
    Editor.init();
    History.init();

    this.bindEvents();
  },

  bindEvents() {
    document.getElementById("themeBtn").onclick = () => {
      State.toggleTheme();
    };

    document.getElementById("sendBtn").onclick = () => this.handleSend();
  },

  setStatus(text, type) {
    const pill = document.getElementById("statusPill");
    pill.textContent = text;
    pill.className = "status-pill";
    if (type) pill.classList.add(type);
  },

  async handleSend() {
    const state = Editor.exportState();

    if (!state.url.trim()) {
      this.setStatus("Missing URL", "error");
      document.getElementById("respBody").textContent =
        "// please provide a URL";
      return;
    }

    State.setEnv(state.env);

    this.setStatus("Sending…", null);
    document.getElementById("respHeaders").textContent =
      "// waiting for response…";
    document.getElementById("respBody").textContent = "";
    document.getElementById("timeInfo").textContent = "… ms";
    document.getElementById("sizeInfo").textContent = "… B";
    document.getElementById("metaInfo").textContent = "";

    try {
      const res = await Transport.execute({
        method: state.method,
        rawUrl: state.url,
        params: state.params,
        headersList: state.headers,
        bodyText: state.body,
        authToken: state.authToken,
        basicUser: state.basicUser,
        basicPass: state.basicPass,
      });

      this.setStatus(
        `${res.status} ${res.statusText}`,
        res.ok ? "ok" : "error",
      );
      document.getElementById("timeInfo").textContent = res.duration + " ms";
      document.getElementById("sizeInfo").textContent = res.size + " B";

      let headerText = "";
      res.headers.forEach((v, k) => {
        headerText += `${k}: ${v}\n`;
      });
      document.getElementById("respHeaders").textContent =
        headerText || "// no headers";

      const json = State.safeParseJSON(res.body);
      if (json !== null) {
        document.getElementById("respBody").textContent = JSON.stringify(
          json,
          null,
          2,
        );
        document.getElementById("metaInfo").textContent = "JSON";
      } else {
        document.getElementById("respBody").textContent =
          res.body || "// empty body";
        document.getElementById("metaInfo").textContent = "TEXT";
      }

      State.pushHistory({
        method: state.method,
        url: Transport.buildUrlWithParams(state.url, state.params), // Save the built URL
        time: res.duration + " ms",
        at: Date.now(),
        ...state,
      });
      History.renderHistory();
    } catch (err) {
      this.setStatus("Network error", "error");
      document.getElementById("respHeaders").textContent = "";
      document.getElementById("respBody").textContent =
        "// " + (err.message || "Unknown error");
      document.getElementById("timeInfo").textContent = "– ms";
      document.getElementById("sizeInfo").textContent = "– B";
    }
  },
};

window.onload = () => App.init();

// js/core/transport.js
const Transport = {
  buildUrlWithParams(baseUrl, params) {
    let url = State.applyEnv(baseUrl);
    const u = new URL(url, "http://dummy-base");
    params.forEach(([k, v]) => {
      const key = State.applyEnv(k);
      const val = State.applyEnv(v);
      if (key) u.searchParams.append(key, val);
    });
    if (/^https?:\/\//i.test(url)) {
      return u.href.replace("http://dummy-base", "");
    }
    return u.pathname + u.search;
  },

  buildHeaders(list, authToken, basicUser, basicPass) {
    const headers = {};
    list.forEach(([k, v]) => {
      const key = State.applyEnv(k);
      const val = State.applyEnv(v);
      if (key) headers[key] = val;
    });
    if (authToken) {
      headers["Authorization"] = "Bearer " + State.applyEnv(authToken);
    } else if (basicUser || basicPass) {
      const token = btoa((basicUser || "") + ":" + (basicPass || ""));
      headers["Authorization"] = "Basic " + token;
    }
    return headers;
  },

  async execute(config) {
    const {
      method,
      rawUrl,
      params,
      headersList,
      bodyText,
      authToken,
      basicUser,
      basicPass,
    } = config;

    if (!rawUrl) throw new Error("Missing URL");

    const url = this.buildUrlWithParams(rawUrl, params);
    const headers = this.buildHeaders(
      headersList,
      authToken,
      basicUser,
      basicPass,
    );
    const options = { method, headers };

    if (bodyText && !["GET", "HEAD"].includes(method)) {
      const bodyApplied = State.applyEnv(bodyText);
      const parsedBody = State.safeParseJSON(bodyApplied);
      if (parsedBody !== null) {
        options.body = JSON.stringify(parsedBody);
        if (!options.headers["Content-Type"])
          options.headers["Content-Type"] = "application/json";
      } else {
        options.body = bodyApplied;
      }
    }

    const started = performance.now();
    try {
      const res = await fetch(url, options);
      const elapsed = Math.round(performance.now() - started);
      const raw = await res.text();
      const size = new TextEncoder().encode(raw).length;

      return {
        ok: res.ok,
        status: res.status,
        statusText: res.statusText,
        headers: res.headers,
        body: raw,
        duration: elapsed,
        size: size,
      };
    } catch (err) {
      throw err;
    }
  },
};

window.Transport = Transport;

// js/components/history.js
class HistoryComponent {
  init() {
    this.renderHistory();
    this.renderSaved();
  }

  renderHistory() {
    const container = document.getElementById("historyList");
    container.innerHTML = "";
    const arr = State.getHistory();

    arr
      .slice()
      .reverse()
      .forEach((item) => {
        const div = document.createElement("div");
        div.className = "list-item";
        div.onclick = (e) => {
          if (e.target.tagName !== "BUTTON") Editor.loadState(item);
        };
        div.innerHTML = `
        <span><strong style="color:var(--accent)">${item.method}</strong> ${item.url}</span>
        <span class="meta">${item.time || ""}</span>
      `;
        container.appendChild(div);
      });
  }

  renderSaved() {
    const container = document.getElementById("savedList");
    container.innerHTML = "";
    const arr = State.getSaved();

    arr.forEach((item, idx) => {
      const div = document.createElement("div");
      div.className = "list-item";
      div.onclick = (e) => {
        if (e.target.tagName !== "BUTTON") Editor.loadState(item);
      };
      div.innerHTML = `
        <span style="font-weight:500;">${item.name}</span>
        <span>
          <button class="small-btn secondary" type="button" onclick="History.deleteSaved(${idx});event.stopPropagation();">Del</button>
        </span>
      `;
      container.appendChild(div);
    });
  }

  clearHistory() {
    State.clearHistory();
    this.renderHistory();
  }

  saveRequest() {
    const method = document.getElementById("method").value;
    const url = document.getElementById("url").value.trim();
    if (!url) return alert("URL is required to save a request.");

    const nameEl = document.getElementById("saveName");
    const name = nameEl.value.trim() || `${method} ${url}`;

    const entry = Editor.exportState();
    entry.name = name;

    State.saveRequest(entry);
    nameEl.value = "";
    this.renderSaved();
  }

  deleteSaved(idx) {
    State.deleteSaved(idx);
    this.renderSaved();
  }
}

window.History = new HistoryComponent();

