/* css/components.css */
header h1 {
  margin: 0;
  font-size: 18px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
header h1 span {
  color: var(--accent);
}

.panel-title {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.panel-title span.badge {
  border-radius: 999px;
  border: 1px solid var(--border);
  padding: 2px 8px;
  font-size: 10px;
  color: var(--muted);
}

.row {
  margin-bottom: 10px;
}
.flex {
  display: flex;
  gap: 8px;
}
.flex-grow {
  flex: 1;
}

label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  margin-bottom: 4px;
}

select,
input,
textarea,
button {
  font-family: inherit;
  font-size: 13px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  padding: 7px 9px;
  outline: none;
}
select:focus,
input:focus,
textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px rgba(56, 189, 248, 0.4);
}
input,
select {
  width: 100%;
}

textarea {
  width: 100%;
  min-height: 110px;
  resize: vertical;
  font-family: ui-monospace, SFMono-Regular, monospace;
  font-size: 12px;
