// js/core/app.js
const App = {
  init() {
    document.documentElement.setAttribute("data-mode", State.theme);

    Tabs.init();
    Editor.init();
    History.init();

    this.bindEvents();
  },

  bindEvents() {
    document.getElementById("themeBtn").onclick = () => {
      State.toggleTheme();
    };

    document.getElementById("sendBtn").onclick = () => this.handleSend();

    // Keyboard Shortcuts
    document.addEventListener("keydown", (e) => {
      // Ctrl/Cmd + Enter to Send Request
      if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
        e.preventDefault();
        this.handleSend();
      }
    });

    // Code Gen Modal Bindings
    document.getElementById("closeCodeModalBtn").onclick = () => {
      document.getElementById("codeModal").style.display = "none";
    };

    document.getElementById("copyCodeBtn").onclick = (e) => {
      const btn = e.target;
      navigator.clipboard.writeText(
        document.getElementById("codeSnippet").innerText,
      );
      btn.innerText = "Copied!";
      setTimeout(() => (btn.innerText = "Copy"), 2000);
    };

    // Code Gen Tabs
    document.querySelectorAll("#codeGenTabs .tab").forEach((tab) => {
      tab.onclick = () => {
        this.switchCodeTab(tab.dataset.target, tab);
      };
    });
  },

  setStatus(text, type) {
    const pill = document.getElementById("statusPill");
    pill.textContent = text;
    pill.className = "status-pill";
    if (type) pill.classList.add(type);
  },

  showCodeGen() {
    const state = Editor.exportState();
    if (!state.url.trim()) {
      // Non-blocking UI notice
      const urlInput = document.getElementById("url");
      const origPlaceholder = urlInput.placeholder;
      urlInput.placeholder = "Error: URL is required!";
      urlInput.value = "";
      setTimeout(() => (urlInput.placeholder = origPlaceholder), 2000);
      return;
    }

    this._codeGenState = state;
    this._currentCodeTab = "curl";

    document.getElementById("codeModal").style.display = "flex";

    // Default to first tab
    const firstTab = document.querySelector("#codeGenTabs .tab");
    this.switchCodeTab("curl", firstTab);
  },

  switchCodeTab(tabName, tabElement) {
    this._currentCodeTab = tabName;

    // Update active tab styling dynamically
    if (tabElement) {
      document
        .querySelectorAll("#codeGenTabs .tab")
        .forEach((t) => t.classList.remove("active"));
      tabElement.classList.add("active");
    }

    // Generate Code
    const s = this._codeGenState;
    State.setEnv(s.env);

    const url = Transport.buildUrlWithParams(s.url, s.params);
    const headers = Transport.buildHeaders(
      s.headers,
      s.authToken,
      s.basicUser,
      s.basicPass,
    );
    let body = s.body;

    if (body && !["GET", "HEAD"].includes(s.method)) {
      const bodyApplied = State.applyEnv(body);
      const parsedBody = State.safeParseJSON(bodyApplied);
      if (parsedBody !== null) {
        body = JSON.stringify(parsedBody);
        if (!headers["Content-Type"])
          headers["Content-Type"] = "application/json";
      } else {
        body = bodyApplied;
      }
    } else {
      body = null;
    }

    let code = "";

    if (tabName === "curl") {
      code = `curl -X ${s.method} "${url}" \\\n`;
      Object.keys(headers).forEach((k) => {
        code += `  -H "${k}: ${headers[k]}" \\\n`;
      });
      if (body) {
        // Escape single quotes for bash
        const escapedBody = body.replace(/'/g, "'\\''");
        code += `  -d '${escapedBody}'`;
      }
      code = code.replace(/ \\\n$/, ""); // Remove trailing slash
    } else if (tabName === "fetch") {
      const opts = { method: s.method, headers: headers };
      if (body) opts.body = "BODY_PLACEHOLDER";

      let optStr = JSON.stringify(opts, null, 2);
      if (body) {
        optStr = optStr.replace(
          '"BODY_PLACEHOLDER"',
          `JSON.stringify(${body})`,
        );
      }

      code = `fetch("${url}", ${optStr})\n  .then(response => response.json())\n  .then(data => console.log(data))\n  .catch(error => console.error('Error:', error));`;
    } else if (tabName === "axios") {
      const opts = { method: s.method, url: url, headers: headers };
      if (body) opts.data = "DATA_PLACEHOLDER";

      let optStr = JSON.stringify(opts, null, 2);
      if (body) {
        optStr = optStr.replace(
          '"DATA_PLACEHOLDER"',
          `JSON.parse('${body.replace(/'/g, "\\'")}')`,
        );
      }

      code = `import axios from 'axios';\n\naxios(${optStr})\n  .then(response => console.log(response.data))\n  .catch(error => console.error(error));`;
    }

    document.getElementById("codeSnippet").innerText = code;
  },

  async handleSend() {
    const state = Editor.exportState();

    if (!state.url.trim()) {
      this.setStatus("Missing URL", "error");
      document.getElementById("respBody").textContent =
        "// please provide a URL";
      return;
    }

    State.setEnv(state.env);

    this.setStatus("Sending…", null);
    document.getElementById("respHeaders").textContent =
      "// waiting for response…";
    document.getElementById("respBody").textContent = "";
    document.getElementById("timeInfo").textContent = "… ms";
    document.getElementById("sizeInfo").textContent = "… B";
    document.getElementById("metaInfo").textContent = "";

    try {
      const res = await Transport.execute({
        method: state.method,
        rawUrl: state.url,
        params: state.params,
        headersList: state.headers,
        bodyText: state.body,
        authToken: state.authToken,
        basicUser: state.basicUser,
        basicPass: state.basicPass,
      });

      this.setStatus(
        `${res.status} ${res.statusText}`,
        res.ok ? "ok" : "error",
      );
      document.getElementById("timeInfo").textContent = res.duration + " ms";
      document.getElementById("sizeInfo").textContent = res.size + " B";

      let headerText = "";
      res.headers.forEach((v, k) => {
        headerText += `${k}: ${v}\n`;
      });
      document.getElementById("respHeaders").textContent =
        headerText || "// no headers";

      const json = State.safeParseJSON(res.body);
      if (json !== null) {
        document.getElementById("respBody").textContent = JSON.stringify(
          json,
          null,
          2,
        );
        document.getElementById("metaInfo").textContent = "JSON";
      } else {
        document.getElementById("respBody").textContent =
          res.body || "// empty body";
        document.getElementById("metaInfo").textContent = "TEXT";
      }

      // Execute Tests
      this.runTests(state.tests, res, json);

      State.pushHistory({
        method: state.method,
        url: Transport.buildUrlWithParams(state.url, state.params), // Save the built URL
        time: res.duration + " ms",
        at: Date.now(),
        ...state,
      });
      History.renderHistory();
    } catch (err) {
      this.setStatus("Network error", "error");
      document.getElementById("respHeaders").textContent = "";
      document.getElementById("respBody").textContent =
        "// " + (err.message || "Unknown error");
      document.getElementById("timeInfo").textContent = "– ms";
      document.getElementById("sizeInfo").textContent = "– B";
    }
  },

  runTests(script, res, json) {
    const list = document.getElementById("testResultsList");
    const badge = document.getElementById("respTestsTabBadge");

    if (!script || !script.trim()) {
      list.innerHTML = `<div style="color:var(--muted); font-style:italic; padding:10px;">No tests executed for this request.</div>`;
      badge.textContent = "Test Results";
      badge.style.color = "";
      return;
    }

    list.innerHTML = "";
    let passedCount = 0;
    let totalCount = 0;

    // Create sandbox environment
    const lx = {
      test: (name, fn) => {
        totalCount++;
        try {
          fn();
          passedCount++;
          list.innerHTML += `<div style="padding:6px 10px; border-bottom:1px solid var(--border); color:var(--success);"><span style="margin-right:8px;">✔</span> ${name}</div>`;
        } catch (e) {
          list.innerHTML += `<div style="padding:6px 10px; border-bottom:1px solid var(--border); color:var(--danger);"><span style="margin-right:8px;">✖</span> ${name}<br><span style="font-size:10px; color:var(--muted); margin-left:20px;">${e.message}</span></div>`;
        }
      },
      expect: (actual) => ({
        to: {
          equal: (expected) => {
            if (actual !== expected)
              throw new Error(`expected ${expected} but got ${actual}`);
          },
          be: {
            true: () => {
              if (actual !== true)
                throw new Error(`expected true but got ${actual}`);
            },
            false: () => {
              if (actual !== false)
                throw new Error(`expected false but got ${actual}`);
            },
          },
        },
        toInclude: (expected) => {
          if (!actual || !actual.includes(expected))
            throw new Error(`expected ${actual} to include ${expected}`);
        },
      }),
    };

    try {
      // Execute the script in a bounded context
      const runFn = new Function("lx", "res", "json", script);
      runFn(lx, res, json);
    } catch (e) {
      list.innerHTML = `<div style="padding:10px; color:var(--danger);">Test Script Syntax Error:<br>${e.message}</div>`;
      badge.textContent = "Tests Failed";
      badge.style.color = "var(--danger)";
      return;
    }

    // Update Badge
    badge.textContent = `Tests (${passedCount}/${totalCount})`;
    badge.style.color =
      passedCount === totalCount && totalCount > 0
        ? "var(--success)"
        : "var(--danger)";
  },

  exportWorkspace() {
    const data = {
      history: State.getHistory(),
      collections: State.getSaved(),
      environment: State.getEnv(),
      exportDate: new Date().toISOString(),
    };
    const dataStr =
      "data:text/json;charset=utf-8," +
      encodeURIComponent(JSON.stringify(data, null, 2));
    const dlAnchorElem = document.createElement("a");
    dlAnchorElem.setAttribute("href", dataStr);
    dlAnchorElem.setAttribute("download", `lxrest_workspace_${Date.now()}.json`);
    dlAnchorElem.click();
    dlAnchorElem.remove();
  },

  importWorkspace() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "application/json";
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target.result);
          if (data.history)
            localStorage.setItem(
              "lxrest_history",
              JSON.stringify(data.history),
            );
          if (data.collections)
            localStorage.setItem(
              "lxrest_saved",
              JSON.stringify(data.collections),
            );
          if (data.environment)
            localStorage.setItem("lxrest_env", data.environment);

          alert("Workspace imported successfully! The page will reload.");
          window.location.reload();
        } catch (err) {
          alert("Invalid workspace file.");
        }
      };
      reader.readAsText(file);
    };
    input.click();
  },
};

window.onload = () => App.init();

