    dlAnchorElem.setAttribute(
      "download",
      `lxrest_${collections.length}_${Date.now()}.json`,
    );
    dlAnchorElem.click();
    dlAnchorElem.remove();
  },

  importWorkspace() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "application/json";
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target.result);
          if (data.history)
            localStorage.setItem(
              "lxrest_history",
              JSON.stringify(data.history),
            );
          if (data.collections)
            localStorage.setItem(
              "lxrest_saved",
              JSON.stringify(data.collections),
            );
          if (data.environment)
            localStorage.setItem("lxrest_env", data.environment);

          alert("Workspace imported successfully! The page will reload.");
          window.location.reload();
        } catch (err) {
          alert("Invalid workspace file.");
        }
      };
      reader.readAsText(file);
    };
    input.click();
  },
};

window.onload = () => App.init();

