      <button class="small-btn" type="button" onclick="this.parentNode.remove()">x</button>
    `;
    document.getElementById("headersList").appendChild(div);
  }

  addEnvRow(key = "", value = "", enabled = true) {
    const div = document.createElement("div");
    div.className = "kv-row";
    div.innerHTML = `
