// js/components/editor.js
class EditorComponent {
  init() {
    this._isSyncing = false;
    this.addParam();
    this.addHeader();

    this.bindEvents();

    // Defer Env loading to loadState or manual trigger, handled by App.init if needed
    // Actually, we load initial state from localStorage manually if history is empty.
    const initialEnv = State.getEnv();
    if (initialEnv) {
      this.loadEnvData(initialEnv);
    } else {
      this.addEnvRow();
    }
  }

  bindEvents() {
    // 1. Bi-directional Sync: URL -> Params
    const urlInput = document.getElementById("url");
    urlInput.addEventListener("input", (e) => {
      this.syncUrlToParams(e.target.value);
    });

    // 2. Bi-directional Sync: Params -> URL (Event Delegation)
    const paramsList = document.getElementById("paramsList");
    paramsList.addEventListener("input", (e) => {
      if (e.target.tagName === "INPUT") {
        this.syncParamsToUrl();
      }
    });

    // 3. Auto JSON Validation on typing
    const bodyInput = document.getElementById("bodyInput");
    const jsonStatus = document.getElementById("jsonStatus");
    bodyInput.addEventListener("input", (e) => {
      const val = e.target.value.trim();
      if (!val) {
        jsonStatus.textContent = "";
        return;
      }
      try {
        JSON.parse(val);
        jsonStatus.textContent = "Valid JSON";
        jsonStatus.style.color = "var(--success)";
      } catch (err) {
        jsonStatus.textContent = "Invalid JSON";
        jsonStatus.style.color = "var(--danger)";
      }
    });

    // 4. Auto-resize textareas
    const textareas = document.querySelectorAll("textarea");
    textareas.forEach((ta) => {
      // Initial sizing
      this.autoResizeTextarea(ta);
      // Resize on input
      ta.addEventListener("input", () => this.autoResizeTextarea(ta));
    });
  }

  autoResizeTextarea(textarea) {
    textarea.style.height = "auto"; // Reset height
    textarea.style.height = textarea.scrollHeight + "px"; // Set to content height
  }

  syncUrlToParams(rawUrl) {
    if (this._isSyncing) return;
    this._isSyncing = true;

    try {
      // Use dummy base to parse search params reliably
      const urlStr = rawUrl.startsWith("http")
        ? rawUrl
        : "http://dummy.com/" + rawUrl.replace(/^\/+/, "");
      const urlObj = new URL(urlStr);

      const paramsList = document.getElementById("paramsList");
      paramsList.innerHTML = ""; // Clear existing

      let hasParams = false;
      urlObj.searchParams.forEach((v, k) => {
        this.addParam(k, v);
        hasParams = true;
      });

      // Always leave one empty row
      if (!hasParams) this.addParam();
    } catch (e) {
      // Ignore invalid URLs while typing
    }

    this._isSyncing = false;
  }

  syncParamsToUrl() {
    if (this._isSyncing) return;
    this._isSyncing = true;

    const urlInput = document.getElementById("url");
    let rawUrl = urlInput.value.trim();

    try {
      // Extract base URL (everything before ?)
      const baseUrlMatch = rawUrl.match(/^([^?]+)/);
      const baseUrl = baseUrlMatch ? baseUrlMatch[1] : rawUrl;

      const params = this.collectKV("paramsList");
      const searchParams = new URLSearchParams();

      params.forEach(([k, v]) => {
        if (k) searchParams.append(k, v);
      });

      const qs = searchParams.toString();
      urlInput.value = qs ? `${baseUrl}?${qs}` : baseUrl;
    } catch (e) {}

    this._isSyncing = false;
  }

  addParam(key = "", value = "") {
    const div = document.createElement("div");
    div.className = "kv-row";
    div.innerHTML = `
      <input placeholder="key" value="${key}">
      <input placeholder="value" value="${value}">
      <button class="small-btn" type="button">x</button>
    `;

    // Bind remove button to also trigger sync
    div.querySelector("button").onclick = () => {
      div.remove();
      this.syncParamsToUrl();
    };

    document.getElementById("paramsList").appendChild(div);
  }

  addHeader(key = "", value = "") {
    const div = document.createElement("div");
    div.className = "kv-row";
    div.innerHTML = `
      <input placeholder="header" value="${key}">
      <input placeholder="value" value="${value}">
      <button class="small-btn" type="button" onclick="this.parentNode.remove()">x</button>
    `;
    document.getElementById("headersList").appendChild(div);
  }

  addEnvRow(key = "", value = "", enabled = true) {
    const div = document.createElement("div");
    div.className = "kv-row";
    div.innerHTML = `
      <input type="checkbox" ${enabled ? "checked" : ""} style="flex: none; width: 14px; height: 14px; margin: 0 6px; cursor: pointer;">
      <input placeholder="key" value="${key}">
      <input placeholder="value" value="${value}">
      <button class="small-btn" type="button" onclick="this.parentNode.remove()">x</button>
    `;
    document.getElementById("envList").appendChild(div);
  }

  clearEnv() {
    if (confirm("Are you sure you want to clear all variables?")) {
      document.getElementById("envList").innerHTML = "";
      document.getElementById("envBulkInput").value = "";
      this.addEnvRow();
    }
  }

  toggleEnvBulk() {
    const kvMode = document.getElementById("envKVMode");
    const bulkMode = document.getElementById("envBulkMode");
    const btn = document.getElementById("envBulkToggleBtn");

    if (kvMode.style.display === "none") {
      // Switching to KV Mode: parse bulk input
      this.syncEnvBulkToKV();
      bulkMode.style.display = "none";
      kvMode.style.display = "flex";
      btn.innerText = "Bulk Edit";
      btn.classList.add("secondary");
    } else {
      // Switching to Bulk Mode: serialize KV to bulk input
      this.syncEnvKVToBulk();
      kvMode.style.display = "none";
      bulkMode.style.display = "flex";
      btn.innerText = "Key-Value Edit";
      btn.classList.remove("secondary");
    }
  }

  syncEnvKVToBulk() {
    const rows = this.collectEnvKV();
    let text = "";
    rows.forEach(([k, v, enabled]) => {
      if (!enabled) text += "# ";
      text += `${k}:${v}\n`;
    });
    const bulkInput = document.getElementById("envBulkInput");
    bulkInput.value = text.trim();
    this.autoResizeTextarea(bulkInput);
  }

  syncEnvBulkToKV() {
    const text = document.getElementById("envBulkInput").value;
    const list = document.getElementById("envList");
    list.innerHTML = "";

    const lines = text.split("\n");
    let hasRows = false;
    lines.forEach((line) => {
      const tLine = line.trim();
      if (!tLine) return;

      let enabled = true;
      let procLine = tLine;
      if (procLine.startsWith("#")) {
        enabled = false;
        procLine = procLine.substring(1).trim();
      }

      const sepIdx = procLine.indexOf(":");
      if (sepIdx !== -1) {
        const k = procLine.substring(0, sepIdx).trim();
        const v = procLine.substring(sepIdx + 1).trim();
        this.addEnvRow(k, v, enabled);
        hasRows = true;
      } else if (procLine) {
        this.addEnvRow(procLine, "", enabled);
        hasRows = true;
      }
    });

    if (!hasRows) this.addEnvRow();
  }

  collectKV(containerId) {
    const rows = document
      .getElementById(containerId)
      .querySelectorAll(".kv-row");
    const out = [];
    rows.forEach((row) => {
      const inputs = row.querySelectorAll("input");
      const k = inputs[0].value.trim();
      const v = inputs[1].value;
      if (k || v) out.push([k, v]); // Collect even if key is empty but value exists
    });
    return out;
  }

  collectEnvKV() {
    const rows = document.getElementById("envList").querySelectorAll(".kv-row");
    const out = [];
    rows.forEach((row) => {
      const cb = row.querySelector("input[type='checkbox']");
      const inputs = row.querySelectorAll("input:not([type='checkbox'])");
      const k = inputs[0].value.trim();
      const v = inputs[1].value;
      if (k || v) out.push([k, v, cb.checked]);
    });
    return out;
  }

  formatBody() {
    const el = document.getElementById("bodyInput");
    const val = el.value.trim();
    if (!val) return;

    const jsonStatus = document.getElementById("jsonStatus");

    try {
      const parsed = JSON.parse(val);
      el.value = JSON.stringify(parsed, null, 2);

      jsonStatus.textContent = "Formatted JSON";
      jsonStatus.style.color = "var(--success)";

      // Revert back to 'Valid JSON' after 2 seconds
      setTimeout(() => {
        if (jsonStatus.textContent === "Formatted JSON") {
          jsonStatus.textContent = "Valid JSON";
        }
      }, 2000);

      this.autoResizeTextarea(el);
    } catch (e) {
      // Flash error instead of alert
      jsonStatus.textContent = "Cannot format: Invalid JSON";
      jsonStatus.style.color = "var(--danger)";
    }
  }

  exportState() {
    // Before export, ensure we filter out completely empty KV rows
    const filterEmpty = (kvArray) =>
      kvArray.filter(([k, v]) => k.trim() !== "");

    // If bulk mode is active, sync to KV first
    if (document.getElementById("envKVMode").style.display === "none") {
      this.syncEnvBulkToKV();
    }

    return {
      method: document.getElementById("method").value,
      url: document.getElementById("url").value,
      params: filterEmpty(this.collectKV("paramsList")),
      headers: filterEmpty(this.collectKV("headersList")),
      body: document.getElementById("bodyInput").value,
      env: this.collectEnvKV(),
      tests: document.getElementById("testsInput").value,
      authToken: document.getElementById("authToken").value,
      basicUser: document.getElementById("basicUser").value,
      basicPass: document.getElementById("basicPass").value,
    };
  }

  loadEnvData(envData) {
    document.getElementById("envList").innerHTML = "";
    if (envData && Array.isArray(envData)) {
      envData.forEach(([k, v, enabled]) => this.addEnvRow(k, v, enabled));
    } else if (typeof envData === "string") {
      // legacy JSON string fallback
      try {
        const parsed = JSON.parse(envData);
        if (Array.isArray(parsed)) {
          parsed.forEach(([k, v, enabled]) => this.addEnvRow(k, v, enabled));
        } else if (typeof parsed === "object") {
          Object.entries(parsed).forEach(([k, v]) =>
            this.addEnvRow(k, v, true),
          );
        } else {
          this.addEnvRow();
        }
      } catch {
        this.addEnvRow();
      }
    } else {
      this.addEnvRow();
    }

    if (document.getElementById("envList").innerHTML === "") this.addEnvRow();

    // If bulk is active, sync to bulk
    if (document.getElementById("envKVMode").style.display === "none") {
      this.syncEnvKVToBulk();
    }
  }

  loadState(data) {
    document.getElementById("method").value = data.method || "GET";

    // We set _isSyncing true so setting URL doesn't overwrite params
    this._isSyncing = true;
    document.getElementById("url").value = data.url || "";

    document.getElementById("paramsList").innerHTML = "";
    if (data.params && data.params.length > 0) {
      data.params.forEach(([k, v]) => this.addParam(k, v));
    } else {
      this.addParam();
    }

    this._isSyncing = false; // Restore

    document.getElementById("headersList").innerHTML = "";
    if (data.headers && data.headers.length > 0) {
      data.headers.forEach(([k, v]) => this.addHeader(k, v));
    } else {
      this.addHeader();
    }

    document.getElementById("bodyInput").value = data.body || "";

    // Trigger json validation update
    document.getElementById("bodyInput").dispatchEvent(new Event("input"));

    if (data.env) this.loadEnvData(data.env);
    if (data.tests) document.getElementById("testsInput").value = data.tests;

    document.getElementById("authToken").value = data.authToken || "";
    document.getElementById("basicUser").value = data.basicUser || "";
    document.getElementById("basicPass").value = data.basicPass || "";
  }
}

window.Editor = new EditorComponent();

